package config

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"regexp"
	"slices"
	"strings"

	"gopkg.in/yaml.v3"

	"github.com/peasant-labs/infra/unstring/internal/failure"
	"github.com/peasant-labs/infra/unstring/internal/rules"
)

// generatedHeader is the marker a generated file carries near its top, in the
// Go convention (`// Code generated by sqlc. DO NOT EDIT.`) that the TS
// generators of the workspace follow too.
var generatedHeader = regexp.MustCompile(`Code generated .*DO NOT EDIT`)

// generatedHeaderLines is how many leading lines are searched for the
// generated header.
const generatedHeaderLines = 20

// calleeName is a TS identifier, optionally a member path (`client.api`).
var calleeName = regexp.MustCompile(`^[A-Za-z_$][A-Za-z0-9_$]*(\.[A-Za-z_$][A-Za-z0-9_$]*)*$`)

// Load reads the config at configPath, decodes it with unknown keys refused,
// applies the documented defaults and validates it against the files under
// the config's directory. Every error is a *failure.Error.
func Load(configPath string) (Config, error) {
	where := "reading " + configPath + ", before any scan. No file was scanned."
	data, err := os.ReadFile(configPath)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return Config{}, failure.New(
				fmt.Sprintf("no config file at %s.", configPath),
				"unstring reads the roots, the baseline path and the exemptions from the repository's config.",
				where,
				"run unstring from the directory that holds "+DefaultPath+", or pass --config PATH.")
		}
		return Config{}, failure.New(
			fmt.Sprintf("the config file %s could not be read: %v.", configPath, err),
			"unstring cannot scan without the repository's config.",
			where,
			"check that the file exists and is readable.")
	}
	return Parse(configPath, data, filepath.Dir(configPath))
}

// Parse decodes and validates config bytes. name is the file name used in
// messages; dir is the directory the config's paths are relative to.
func Parse(name string, data []byte, dir string) (Config, error) {
	where := "reading " + name + ", before any scan. No file was scanned."
	var c Config
	dec := yaml.NewDecoder(bytes.NewReader(data))
	dec.KnownFields(true)
	if err := dec.Decode(&c); err != nil {
		if errors.Is(err, io.EOF) {
			return Config{}, failure.New(
				fmt.Sprintf("the config file %s is empty.", name),
				"a config needs at least `version: 1` and the roots of one language.",
				where,
				"write the config as the infra AGENTS.md documents it, for example `version: 1` and `ts: {roots: [src]}`.")
		}
		return Config{}, failure.New(
			fmt.Sprintf("the config file %s does not decode: %v.", name, err),
			"unstring refuses unknown keys and wrong value types so that a misspelt setting cannot be silently ignored.",
			where,
			"correct the key or value on the line named above; the keys are version, baseline, ts, go, schema, endpoints, dataDirs and exempt.")
	}
	fail := func(what, why, fix string) (Config, error) {
		return Config{}, failure.New(what, why, where, fix)
	}

	if c.Version != FormatVersion {
		return fail(
			fmt.Sprintf("%s has `version: %d`; this tool reads only `version: %d`.", name, c.Version, FormatVersion),
			"the version says which keys the file may hold, and a config written for another version may mean something else.",
			fmt.Sprintf("set `version: %d`, or run the unstring release the config was written for.", FormatVersion))
	}
	if c.Baseline == "" {
		c.Baseline = DefaultBaselinePath
	}
	if msg := relativePathProblem(c.Baseline); msg != "" {
		return fail(
			fmt.Sprintf("the baseline path %q in %s %s.", c.Baseline, name, msg),
			"every path unstring reads or writes is relative to the config's directory, with `/` separators.",
			"write the baseline path relative to the config, for example "+DefaultBaselinePath+".")
	}
	if c.TS == nil && c.Go == nil {
		return fail(
			fmt.Sprintf("%s names no roots: it has neither a `ts` nor a `go` section.", name),
			"unstring scans only the roots the config names, so with none there is nothing to guard.",
			"add `ts: {roots: [<dir>]}`, `go: {roots: [<dir>]}`, or both.")
	}
	for _, lang := range rules.AllLangs {
		key, roots := lang.String(), c.section(lang)
		if roots == nil {
			continue
		}
		if len(roots.Roots) == 0 {
			return fail(
				fmt.Sprintf("the `%s` section of %s has no roots.", key, name),
				"a language section is scanned only under its roots.",
				fmt.Sprintf("list at least one directory under `%s.roots`, or remove the section.", key))
		}
		for _, r := range roots.Roots {
			if msg := relativePathProblem(r); msg != "" {
				return fail(
					fmt.Sprintf("the %s root %q in %s %s.", key, r, name, msg),
					"roots are relative to the config's directory, with `/` separators.",
					"write the root relative to the config, for example `frontend` or `.`.")
			}
			info, err := os.Stat(filepath.Join(dir, filepath.FromSlash(r)))
			if err != nil || !info.IsDir() {
				return fail(
					fmt.Sprintf("the %s root %q in %s is not a directory under %s.", key, r, name, dir),
					"a root that does not exist would scan nothing, and the baseline would silently cover less than intended.",
					"correct the root, or remove it from the config.")
			}
		}
	}
	if c.Schema.Module != "" && strings.ContainsAny(c.Schema.Module, " \t@") {
		return fail(
			fmt.Sprintf("the schema module %q in %s is not a module path.", c.Schema.Module, name),
			"the module is resolved with `go mod download`, which takes a module path; its version comes from go.mod or package.json.",
			"write the module path alone, for example `github.com/peasant-labs/schema`.")
	}

	if len(c.Endpoints.Prefixes) == 0 {
		c.Endpoints.Prefixes = DefaultEndpointPrefixes()
	}
	for _, p := range c.Endpoints.Prefixes {
		if !strings.HasPrefix(p, "/") || strings.ContainsAny(p, " \t") {
			return fail(
				fmt.Sprintf("the endpoint prefix %q in %s does not start with `/`.", p, name),
				"an endpoint prefix is the start of an API path, such as /api/v1.",
				"write the prefix as an absolute path, for example \"/api/v1\".")
		}
	}
	for _, callee := range c.Endpoints.Callees {
		if !calleeName.MatchString(callee) {
			return fail(
				fmt.Sprintf("the endpoint callee %q in %s is not a TS identifier.", callee, name),
				"a callee is the name of a function whose first argument is an API path.",
				"write the function's name, for example `api`.")
		}
	}
	for _, f := range c.Endpoints.MountFiles {
		if msg := relativePathProblem(f); msg != "" {
			return fail(
				fmt.Sprintf("the mount file %q in %s %s.", f, name, msg),
				"mount files are relative to the config's directory, with `/` separators.",
				"write the router file's path relative to the config.")
		}
	}
	if len(c.DataDirs) == 0 {
		c.DataDirs = DefaultDataDirs()
	}
	for _, d := range c.DataDirs {
		if d == "" || strings.ContainsAny(d, "/\\ \t") {
			return fail(
				fmt.Sprintf("the data directory %q in %s is not a single directory name.", d, name),
				"the data-path rules look for a directory name as one path segment.",
				"write a bare name such as `testdata`.")
		}
	}

	for i, e := range c.Exempt {
		label := fmt.Sprintf("exempt entry %d (rule %q) in %s", i+1, e.Rule, name)
		if e.Rule != ExemptAllRules {
			if _, err := rules.ParseRuleID(e.Rule); err != nil {
				return fail(
					fmt.Sprintf("%s names a rule that does not exist.", label),
					err.Error()+".",
					"name one rule id, or \"*\" for generated code; `unstring show rules` lists the ids.")
			}
		}
		if len(e.Paths) == 0 {
			return fail(
				fmt.Sprintf("%s lists no paths.", label),
				"an exemption applies to the files its paths match, so an entry with none exempts nothing.",
				"list the exempt files or globs under `paths`, or remove the entry.")
		}
		for _, p := range e.Paths {
			if msg := relativePathProblem(strings.ReplaceAll(p, "*", "x")); msg != "" {
				return fail(
					fmt.Sprintf("%s has the path %q, which %s.", label, p, msg),
					"exempt paths are relative to the config's directory, with `/` separators.",
					"write the path or glob relative to the config, for example `backend/internal/db/gen/**`.")
			}
			if _, err := path.Match(globSegments(p), ""); err != nil {
				return fail(
					fmt.Sprintf("%s has the malformed glob %q.", label, p),
					"exempt paths are globs with `*`, `?`, `[…]` and `**` for any number of directories.",
					"correct the glob.")
			}
		}
		if len(strings.Fields(e.Reason)) == 0 {
			return fail(
				fmt.Sprintf("%s has no reason.", label),
				"an exemption removes the guard from a file, so it says why, for the reviewer and for whoever burns the baseline down.",
				"add `reason: <why this site is exempt>` to the entry.")
		}
		if exemptCoversClosedSet(e.Rule) {
			if ferr := requireGeneratedFiles(dir, name, label, e); ferr != nil {
				return Config{}, ferr
			}
		}
	}
	return c, nil
}

// exemptCoversClosedSet reports whether an exempt entry for this rule value
// removes either closed-set rule, which only generated files may be exempt
// from.
func exemptCoversClosedSet(rule string) bool {
	if rule == ExemptAllRules {
		return true
	}
	id := rules.RuleID(rule)
	return id.Origin() == rules.OriginGenerated
}

// requireGeneratedFiles walks the files an exempt entry matches and refuses
// the config when one of them lacks a generated header.
func requireGeneratedFiles(dir, name, label string, e Exempt) error {
	for _, p := range e.Paths {
		base := globBase(p)
		root := filepath.Join(dir, filepath.FromSlash(base))
		err := filepath.WalkDir(root, func(full string, d fs.DirEntry, err error) error {
			if err != nil {
				if errors.Is(err, fs.ErrNotExist) {
					return nil
				}
				return err
			}
			if d.IsDir() {
				if d.Name() == ".git" || d.Name() == "node_modules" {
					return filepath.SkipDir
				}
				return nil
			}
			rel, err := filepath.Rel(dir, full)
			if err != nil {
				return err
			}
			rel = filepath.ToSlash(rel)
			if !MatchPath(p, rel) {
				return nil
			}
			ok, err := hasGeneratedHeader(full)
			if err != nil {
				return err
			}
			if !ok {
				return failure.New(
					fmt.Sprintf("%s matches the hand-written file %s.", label, rel),
					"an exemption that covers closed-set-literal or go-closed-set-literal is accepted only for generated code: "+
						"a hand-written file has no exemption from those rules, because the fix for a set value is always the typed value.",
					"reading "+name+", before any scan. No file was scanned.",
					fmt.Sprintf("narrow the entry's paths to files that carry a `Code generated … DO NOT EDIT` header, "+
						"or name a rule other than the two closed-set rules; then fix the literals in %s.", rel))
			}
			return nil
		})
		if err != nil {
			var ferr *failure.Error
			if errors.As(err, &ferr) {
				return ferr
			}
			return failure.New(
				fmt.Sprintf("the files matched by %s could not be read: %v.", label, err),
				"unstring checks that every file an exemption of the closed-set rules matches is generated.",
				"reading "+name+", before any scan. No file was scanned.",
				"check the permissions of the matched files.")
		}
	}
	return nil
}

func hasGeneratedHeader(file string) (bool, error) {
	f, err := os.Open(file)
	if err != nil {
		return false, err
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 64*1024), 1024*1024)
	for i := 0; i < generatedHeaderLines && sc.Scan(); i++ {
		if generatedHeader.Match(sc.Bytes()) {
			return true, nil
		}
	}
	return false, sc.Err()
}

// relativePathProblem returns why p is not a clean relative path with `/`
// separators inside the config directory, or "" when it is one.
func relativePathProblem(p string) string {
	switch {
	case p == "":
		return "is empty"
	case strings.Contains(p, "\\"):
		return "uses `\\` separators"
	case path.IsAbs(p) || filepath.IsAbs(p):
		return "is absolute"
	case path.Clean(p) != p:
		return "is not in clean form (" + path.Clean(p) + ")"
	case p == ".." || strings.HasPrefix(p, "../"):
		return "leaves the config's directory"
	}
	return ""
}

// RootsFor returns the configured roots of one language, or nil.
func (c Config) RootsFor(l rules.Lang) []string {
	r := c.section(l)
	if r == nil {
		return nil
	}
	return slices.Clone(r.Roots)
}

// section returns the config section of l's roots, keyed in the file by
// l.String(); nil when the file has none or l is not in rules.AllLangs.
func (c Config) section(l rules.Lang) *Roots {
	switch l {
	case rules.LangTS:
		return c.TS
	case rules.LangGo:
		return c.Go
	}
	return nil
}

// Params returns the settings that shape the static rules.
func (c Config) Params() rules.Params {
	return rules.Params{
		EndpointPrefixes: slices.Clone(c.Endpoints.Prefixes),
		EndpointCallees:  slices.Clone(c.Endpoints.Callees),
		MountFiles:       slices.Clone(c.Endpoints.MountFiles),
		DataDirs:         slices.Clone(c.DataDirs),
	}
}

// Exempted reports whether an exempt entry removes hits of rule id in file.
// file is relative to the config's directory, with `/` separators.
func (c Config) Exempted(id rules.RuleID, file string) bool {
	for _, e := range c.Exempt {
		if e.Rule != ExemptAllRules && e.Rule != id.String() {
			continue
		}
		for _, p := range e.Paths {
			if MatchPath(p, file) {
				return true
			}
		}
	}
	return false
}
